import React from 'react';
import { Handle } from 'reactflow';

// Color mapping for each node type
const NODE_COLORS = {
  customInput: { header: '#0ea5e9', bg: '#f0f9ff' }, // Blue
  llm: { header: '#8b5cf6', bg: '#f3e8ff' },         // Purple
  customOutput: { header: '#ec4899', bg: '#fdf2f8' }, // Pink
  text: { header: '#10b981', bg: '#f0fdf4' },         // Green
  math: { header: '#f59e0b', bg: '#fffbeb' },         // Amber
  api: { header: '#3b82f6', bg: '#dbeafe' },          // Light Blue
  condition: { header: '#ef4444', bg: '#fef2f2' },    // Red
  csv: { header: '#059669', bg: '#f0fdf4' },          // Emerald
  custom: { header: '#6b7280', bg: '#f3f4f6' },       // Gray
};

const BaseNode = ({ data, type }) => {
  const { label, handles = [], content } = data;
  const colors = NODE_COLORS[type] || NODE_COLORS.custom; // fallback

  return (
    <div
      style={{
        width: '220px',
        borderRadius: '8px',
        border: `1px solid ${colors.header}`,
        backgroundColor: colors.bg,
        boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        fontFamily: "'Inter', sans-serif",
      }}
    >
      <div
        style={{
          padding: '8px 12px',
          backgroundColor: colors.header,
          color: 'white',
          fontSize: '13px',
          fontWeight: 600,
          borderBottom: `1px solid ${colors.header}`,
        }}
      >
        {label || type}
      </div>
      <div style={{ padding: '10px 12px', fontSize: '13px', color: '#374151' }}>
        {content}
      </div>
      {handles.map(h => (
        <Handle
          key={h.id}
          type={h.type}
          position={h.position}
          id={h.id}
          style={{
            width: '12px',
            height: '12px',
            background: colors.header,
            border: '2px solid white',
          }}
        />
      ))}
    </div>
  );
};

export default BaseNode;
